#[test]
fn bare_frontmatter_update_document_preserves_meta() {
    // Simulate what the LSP does: update_document with raw content
    let opts = MarkdownOptions {
        bare_frontmatter: true,
        ..Default::default()
    };
    let mut graph = Graph::import(
        &vec![("1".to_string(), "title: Task A\nstatus: ready\n\n# Task A\n".to_string())].into_iter().collect(),
        opts.clone(),
